// We use a fallback OR (||) operator. 
// If the server didn't provide a port in the environment, fallback to 3000.
const PORT = process.env.PORT || 3000;

console.log(`Connecting to database at: ${process.env.DB_HOST || 'localhost'}`);
console.log(`Server starting on port: ${PORT}`);

// SECURITY CHECK
if (!process.env.STRIPE_KEY) {
  console.warn("WARNING: Stripe key missing. Payments will fail!");
}
